import json
import boto3
import os

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ.get('ORDERS_TABLE', 'orders'))

def lambda_handler(event, context):
    """Retrieve order details by order ID.

    Expected path: GET /orders/{order_id}
    Authorization: Bearer token in headers provides user identity
    """
    try:
        # Extract user identity from authorizer context
        request_context = event.get('requestContext', {})
        authorizer = request_context.get('authorizer', {})
        caller_user_id = authorizer.get('claims', {}).get('sub', '')

        # Extract order_id from path parameters
        path_params = event.get('pathParameters', {})
        order_id = path_params.get('order_id', '')

        if not order_id:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'order_id is required'})
            }

        # VULNERABILITY: No ownership check - any authenticated user can
        # retrieve any order by guessing/enumerating order_id values
        response = table.get_item(
            Key={'order_id': order_id}
        )

        item = response.get('Item')
        if not item:
            return {
                'statusCode': 404,
                'body': json.dumps({'error': 'Order not found'})
            }

        # Log access for audit trail (but doesn't prevent unauthorized access)
        print(f"Order {order_id} accessed by user {caller_user_id}")

        # Return full order details including PII
        return {
            'statusCode': 200,
            'headers': {
                'Content-Type': 'application/json',
                'X-Request-User': caller_user_id
            },
            'body': json.dumps({
                'order_id': item.get('order_id'),
                'user_id': item.get('user_id'),
                'items': item.get('items', []),
                'total': str(item.get('total', 0)),
                'shipping_address': item.get('shipping_address', {}),
                'payment_last_four': item.get('payment_last_four', ''),
                'status': item.get('status', 'unknown')
            })
        }

    except Exception as e:
        print(f"Error processing request: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal server error'})
        }


def batch_handler(event, context):
    """Batch retrieve multiple orders - internal use.

    Expected: POST /orders/batch with body {"order_ids": [...]}
    """
    try:
        body = json.loads(event.get('body', '{}'))
        order_ids = body.get('order_ids', [])

        if not order_ids or len(order_ids) > 25:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Provide 1-25 order_ids'})
            }

        keys = [{'order_id': oid} for oid in order_ids]
        response = dynamodb.batch_get_item(
            RequestItems={
                os.environ.get('ORDERS_TABLE', 'orders'): {
                    'Keys': keys
                }
            }
        )

        items = response.get('Responses', {}).get(
            os.environ.get('ORDERS_TABLE', 'orders'), []
        )

        return {
            'statusCode': 200,
            'body': json.dumps({'orders': items}, default=str)
        }

    except Exception as e:
        print(f"Batch error: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal server error'})
        }
